-- SQLite: 서로 독립적인 두 표를 각각 먼저 집계합니다.
CREATE TABLE member(id INTEGER PRIMARY KEY);
CREATE TABLE loan(id TEXT PRIMARY KEY NOT NULL, member INTEGER NOT NULL);
CREATE TABLE entry(id TEXT PRIMARY KEY NOT NULL, member INTEGER NOT NULL);
INSERT INTO member VALUES (1),(2);
INSERT INTO loan VALUES ('L1',1),('L2',1);
INSERT INTO entry VALUES ('E1',1),('E2',1),('E3',1);
WITH l AS (SELECT member,COUNT(*) AS n FROM loan GROUP BY member),
     e AS (SELECT member,COUNT(*) AS n FROM entry GROUP BY member)
SELECT m.id,COALESCE(l.n,0),COALESCE(e.n,0) FROM member AS m
LEFT JOIN l ON l.member=m.id LEFT JOIN e ON e.member=m.id ORDER BY m.id;
